const allCodes = ["en","tr","de","fr","it","es","nl","pl","pt","ro","sv","da","fi","cs","sk","hu","el","bg","ru","uk","ar","zh","ja","ko","hi"];

const sister = {
  it: "es", nl: "de", pl: "de", pt: "es", ro: "es",
  sv: "de", da: "de", fi: "de", cs: "de", sk: "cs",
  hu: "de", el: "en", bg: "ru", ru: "en", uk: "ru",
  ar: "en", zh: "en", ja: "en", ko: "en", hi: "en"
};

function buildLocale(code) {
  let base;
  if (locales[code]) {
    base = { ...en, ...locales[code] };
  } else if (sister[code] && locales[sister[code]]) {
    base = { ...en, ...locales[sister[code]] };
  } else {
    base = { ...en };
  }
  if (langOverrides[code]) Object.assign(base, langOverrides[code]);
  return base;
}

const output = { en };
allCodes.filter(c => c !== "en").forEach(code => { output[code] = buildLocale(code); });

// Verify completeness
allCodes.forEach(code => {
  const missing = Object.keys(en).filter(k => !output[code][k]);
  if (missing.length) console.warn(code, "missing", missing.length, "keys");
});

const js = `/* T-V-K Vision Platform — ${allCodes.length} languages, ${Object.keys(en).length} keys each */\nconst TVK_TRANSLATIONS = ${JSON.stringify(output, null, 2)};\n`;
writeFileSync("js/translations.js", js);
console.log("Wrote js/translations.js");
